/* global __firebase_config, __app_id, __initial_auth_token */
import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, LogOut, Shield, User, GraduationCap, ArrowRight,
  Settings, ShieldCheck, Map, Wallet, BookOpen, Globe, Award, 
  Save, Clock, Phone, ChevronRight, MessageSquare, Bell, Calendar,
  Search, Send, LayoutDashboard
} from 'lucide-react';

// Firebase Imports
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously, signInWithCustomToken, onAuthStateChanged } from 'firebase/auth';
import { getFirestore, doc, setDoc, onSnapshot } from 'firebase/firestore';

// Your Specific Firebase Configuration
const myFirebaseConfig = {
  apiKey: "AIzaSyDutEHTfbkM9kDayAtCx3R9ZHIyxpuQJMA",
  authDomain: "studentsuccessai-611f1.firebaseapp.com",
  projectId: "studentsuccessai-611f1",
  storageBucket: "studentsuccessai-611f1.firebasestorage.app",
  messagingSenderId: "406714339262",
  appId: "1:406714339262:web:e439a293efcc7de2a8b3ef"
};

/**
 * LOCAL FIX: Using a try-catch/typeof check for environment variables.
 * In your local PC, these __ variables don't exist, so we default to your myFirebaseConfig.
 */
const firebaseConfig = (typeof __firebase_config !== 'undefined') ? JSON.parse(__firebase_config) : myFirebaseConfig;
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

// Use your Project ID as the default appId for local development
const appId = (typeof __app_id !== 'undefined') ? __app_id : 'studentsuccessai-611f1';

const API_URL = "http://127.0.0.1:8000";

// --- SUB-COMPONENT: STUDENT DASHBOARD ---
const StudentDashboard = ({ user }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [profile, setProfile] = useState({
    firstName: "Juan",
    lastName: "Dela Cruz",
    email: "juan.delacruz@university.edu.ph",
    phone: "+63 912 345 6789",
    avatar: "https://api.dicebear.com/7.x/avataaars/svg?seed=Juan",
    bio: "Sophomore Computer Science student focused on AI and accessibility.",
    interests: ["Artificial Intelligence", "Community Development", "Web Technologies"]
  });

  useEffect(() => {
    if (!user) return;
    
    // Strict path logic /artifacts/{appId}/users/{userId}/{collectionName}
    const profileDocRef = doc(db, 'artifacts', appId, 'users', user.uid, 'settings', 'profile');

    const unsubscribe = onSnapshot(profileDocRef, (docSnap) => {
      if (docSnap.exists()) {
        setProfile(docSnap.data());
      }
    }, (error) => {
      console.error("Firestore Error:", error);
    });

    return () => unsubscribe();
  }, [user]);

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    if (!user) return;
    try {
      const profileDocRef = doc(db, 'artifacts', appId, 'users', user.uid, 'settings', 'profile');
      await setDoc(profileDocRef, profile);
      console.log("Profile saved to Firebase!");
    } catch (err) {
      console.error("Save failed:", err);
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
    { id: 'roadmap', label: 'My Roadmap', icon: <Map size={20} /> },
    { id: 'messages', label: 'Messages', icon: <MessageSquare size={20} /> },
    { id: 'profile', label: 'My Profile', icon: <User size={20} /> },
  ];

  return (
    <div className="flex flex-col lg:flex-row gap-8 items-start">
      <div className="w-full lg:w-64 shrink-0 bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-2">
        {navItems.map(item => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl font-bold text-sm transition-all ${
              activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-400 hover:bg-slate-50'
            }`}
          >
            {item.icon} {item.label}
          </button>
        ))}
      </div>

      <div className="flex-1 w-full">
        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-8 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl">
               <div>
                  <h2 className="text-2xl font-black mb-1">Cloud Sync: Active</h2>
                  <p className="text-indigo-100 text-sm">Your socioeconomic data is encrypted and secure.</p>
               </div>
               <ShieldCheck size={48} className="opacity-40" />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Current Risk</p>
                  <p className="text-4xl font-black text-indigo-600">12%</p>
                  <p className="text-xs text-slate-500 mt-2 font-medium">Low risk of attrition based on AI analysis.</p>
               </div>
               <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Academic standing</p>
                  <p className="text-4xl font-black text-emerald-500">Good</p>
                  <p className="text-xs text-slate-500 mt-2 font-medium">GPA and Attendance meet scholarship criteria.</p>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'profile' && (
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-xl max-w-2xl">
            <div className="flex justify-between items-center mb-6">
               <h2 className="text-xl font-black">Student Information</h2>
               <div className="px-3 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-bold rounded-full uppercase tracking-widest">Firestore Saved</div>
            </div>
            <form onSubmit={handleSaveProfile} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">First Name</label>
                  <input 
                    className="w-full p-4 bg-slate-50 rounded-2xl outline-none border border-slate-100 focus:border-indigo-500 transition-all font-bold" 
                    value={profile.firstName} 
                    onChange={e => setProfile({...profile, firstName: e.target.value})}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Last Name</label>
                  <input 
                    className="w-full p-4 bg-slate-50 rounded-2xl outline-none border border-slate-100 focus:border-indigo-500 transition-all font-bold" 
                    value={profile.lastName} 
                    onChange={e => setProfile({...profile, lastName: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Bio / Aspirations</label>
                <textarea 
                  className="w-full p-4 bg-slate-50 rounded-2xl outline-none border border-slate-100 focus:border-indigo-500 transition-all text-sm leading-relaxed" 
                  value={profile.bio} 
                  onChange={e => setProfile({...profile, bio: e.target.value})}
                  rows="4"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-indigo-600 transition-all shadow-lg shadow-slate-200">
                <Save size={18} /> Update Cloud Profile
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

// Placeholder components for Admin/Teacher
const AdminDashboard = () => <div className="p-12 bg-white rounded-[3rem] border border-dashed border-slate-300 text-center text-slate-400 font-bold">Admin Cloud Interface Loading...</div>;
const TeacherDashboard = () => <div className="p-12 bg-white rounded-[3rem] border border-dashed border-slate-300 text-center text-slate-400 font-bold">Teacher Cloud Interface Loading...</div>;

// --- MAIN APP COMPONENT ---
export default function App() {
  const [sessionUser, setSessionUser] = useState(null);
  const [appRole, setAppRole] = useState(null);

  useEffect(() => {
    const initAuth = async () => {
      try {
        // LOCAL CHECK: Safely check for local tokens vs cloud tokens
        if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
          await signInWithCustomToken(auth, __initial_auth_token);
        } else {
          // Default local behavior: Sign in anonymously to your Firebase project
          await signInAnonymously(auth);
        }
      } catch (err) { 
        console.error("Auth failed:", err); 
      }
    };
    initAuth();
    const unsubscribe = onAuthStateChanged(auth, setUser => setSessionUser(setUser));
    return () => unsubscribe();
  }, []);

  const handleLogin = (role) => setAppRole(role);
  const handleLogout = () => setAppRole(null);

  if (!appRole) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white">
        <div className="bg-[#0f172a] p-12 rounded-[3.5rem] shadow-2xl border border-slate-800 w-full max-w-md text-center">
          <div className="bg-indigo-500/10 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-indigo-500/20">
            <BrainCircuit className="text-indigo-400 w-12 h-12" />
          </div>
          <h1 className="text-white text-4xl font-black mb-2 tracking-tighter">SUCCESS<span className="text-indigo-500">PREDICT</span></h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em] mb-10">AI Socioeconomic Monitor</p>
          <div className="space-y-3">
            {[
              { id: 'admin', label: 'Administrator', icon: <Shield size={18}/> },
              { id: 'teacher', label: 'Faculty / Teacher', icon: <User size={18}/> },
              { id: 'student', label: 'Student Portal', icon: <GraduationCap size={18}/> }
            ].map(role => (
              <button 
                key={role.id}
                onClick={() => handleLogin(role.id)}
                className="w-full py-5 px-6 bg-slate-800 hover:bg-indigo-600 text-white rounded-[1.5rem] font-bold flex items-center justify-between group transition-all"
              >
                <span className="flex items-center gap-3">{role.icon} {role.label}</span>
                <ArrowRight size={18} className="opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
              </button>
            ))}
          </div>
          <div className="mt-8 pt-6 border-t border-slate-800/50">
             <p className="text-[10px] text-slate-500 font-medium">
               {sessionUser ? `Connected to: ${firebaseConfig.projectId}` : "Syncing to Cloud..."}
             </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans">
      <nav className="bg-white/80 backdrop-blur-md border-b sticky top-0 z-50 px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2 font-black text-2xl tracking-tighter">
          <div className="bg-indigo-600 p-2 rounded-xl text-white"><BrainCircuit size={20}/></div>
          SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        <div className="flex items-center gap-6">
          <div className="hidden sm:block text-right">
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest leading-none mb-1">{appRole}</p>
            <p className="text-sm font-bold text-slate-700 leading-none capitalize">{appRole} Access</p>
          </div>
          <button onClick={handleLogout} className="bg-red-50 text-red-500 p-3 rounded-2xl hover:bg-red-100 transition-all"><LogOut size={20} /></button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-4 sm:p-8 animate-in fade-in duration-500">
        {appRole === 'admin' && <AdminDashboard />}
        {appRole === 'teacher' && <TeacherDashboard />}
        {appRole === 'student' && <StudentDashboard user={sessionUser} />}
      </main>
    </div>
  );
}
